import os,subprocess,sys,json
for name,sel in [('003',r'\\. |\\[|\\{|\\+|\\-|\\*|/|%'),('004',r'%%FAIL|if |try |reduce |foreach |def | as |label |module|include')]:
 p=subprocess.run([sys.executable,'sources/run_conformance.py','--select',sel,'--json'],capture_output=True,text=True,env={**os.environ,'JQ':os.getcwd()+'/jq'},timeout=180)
 open('/tmp/new'+name+'.json','w').write(p.stdout)
 d=json.loads(p.stdout); print(name,d['summary'])
 for c in d['cases']:
  if c['status']=='fail': print(c['line'],c['program'])
PY"

